declare @h_line1 as nvarchar(128), @h_line2 as nvarchar(128), @h_line3 as nvarchar(128), @h_line4 as nvarchar(128), @reportType varchar(1)
select @h_line1 = case when @@language = 'V' then cname else cname2 end from reports where ccode = 'DEC093'
select @h_line2 = case when @@language = 'V' then cname else cname2 end from reports where ccode = 'DEC094'
select @h_line3 = case when @@language = 'V' then cname else cname2 end from reports where ccode = 'DEC095'
select @h_line4 = case when @@language = 'V' then cname else cname2 end from reports where ccode = 'DEC096'
select @reportType = rtrim(val) from options where name = 'm_kieu_bc'
--select @mau_bc = substring(@mau_bc, 2, 1)

create table #tmp (quy int, nam int)
insert into #tmp exec FastBusiness$Report$GetQuaterAndYear @ngay1, @ngay2
--select @nam = nam from #tmp
drop table #tmp
declare @title nvarchar(max), @titleBI nvarchar(max)
select @title = 
	case @bc_theo
			when 0 then 
					case when @@language = 'V' 
							 then N'Từ ngày ' + convert(Nvarchar(10), @ngay1, 103) + N' đến ngày ' + convert(Nvarchar(10), @ngay2, 103)
							 else N'From '     + convert(Nvarchar(10), @ngay1, 103) + N' to '       + convert(Nvarchar(10), @ngay2, 103) END
			when 1 then 
					case when @@language = 'V' 
							 then N'Tháng ' + right('0' + cast(@thang as varchar(2)), 2) + N' năm ' + cast(@nam as varchar(4))
							 else N'Month ' + right('0' + cast(@thang as varchar(2)), 2) + N' Year ' + cast(@nam as varchar(4)) END
			when 2 then 
					case when @@language = 'V' 
							 then N'Quý ' + cast(@quy as varchar(1)) + N' năm ' + cast(@nam as varchar(4))
							 else N'Quarter ' + cast(@quy as varchar(1)) + N' Year ' + cast(@nam as varchar(4)) END
			when 3 then 
					case when @@language = 'V' 
							 then N'Năm ' + cast(@nam as varchar(4))
							 else N'Year ' + cast(@nam as varchar(4)) END
			else N''
	END
select @titleBI = 
	case @bc_theo
			when 0 then N'Từ ngày ( Date from) ' + convert(Nvarchar(10), @ngay1, 103) + N' đến ngày (to) ' + convert(Nvarchar(10), @ngay2, 103)
			when 1 then N'Tháng (Month) ' + right('0' + cast(@thang as varchar(2)), 2) + N' năm (year) ' + cast(@nam as varchar(4))
			when 2 then N'Quý (Quarter) ' + cast(@quy as varchar(1)) + N' năm (year) ' + cast(@nam as varchar(4))
			when 3 then N'Năm (Year) ' + cast(@nam as varchar(4))
			else N''
	END

select cast(@ngay1 as smalldatetime) as date_from, cast(@ngay2 as smalldatetime) as date_to, @h_line1 as h_line1, @h_line2 as h_line2, @h_line3 as h_line3, @h_line4 as h_line4, isnull(@reportType, '') as kieu_bc
	, case when @nam <> 0 then @nam else year(@ngay1) end as nam_tc, @bc_theo as bc_theo, @quy as quy, @thang as thang, @title as title, @titleBI as titleBI
exec zrs_rptBankBalance @ngay1, @ngay2, @ma_dvcs, @tknh,  @@language, @@userID, @@admin, default








