/* </flatten> */
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);

	if (f._convection) f._convection = null;

	changeLookupReadonly(f, 'ma_dvcs');

	var bcTheoItem = f.getItem('bc_theo');
	if (!f._isInitialized) {
		f.getItem('thang').disabled = true;
		f.getItem('quy').disabled = true;
		f.getItem('nam').disabled = true;
		f._isInitialized = true;
		f.getItem('bc_theo').focus();
	} else {
		_applyReportTypeState(f, true, false);
	}
	&ReportSign.Filter.Active;
	f.setReferenceKeyFilter('tknh');
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(f) {try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, d1 = f.getItem('ngay1').value, d2 = f.getItem('ngay2').value, x = f.getItemValue('mau_bc');
			g._hiddenFields = [
				{Fields: 'no_dk_nt, co_dk_nt, ps_no_nt, ps_co_nt, no_ck_nt, co_ck_nt', Value: (x == '001')},
			];
			g._hiddenForms = [
				{Form: [2, 3, 4, 5, 8, 9, 10, 11, 15, 16, 17, 18, 21, 22, 23, 24], Value: (x == '001' || x == '002')},
				{Form: [0, 1, 4, 5, 6, 7, 10, 11, 13, 14, 17, 18, 19, 20, 23, 24], Value: (x == '011' || x == '012')},
				{Form: [0, 1, 2, 3, 6, 7, 8, 9, 13, 14, 15, 16, 19, 20, 21, 22], Value: (x == '021' || x == '022')}
			];
			g._alterTitle = [null, [['%d1', d1, true], ['%d2', d2, true]]];
			g._queryFilterString = getQueryFilterString(f, 'mau_bc, ngay1, ngay2, ma_dvcs, tk_1, xem_tk_nh, fcode4');
			g._$xem_tk_nh = 1;
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

function onchange$ReportType(o) {
	var f = o.parentForm, s = o.field.Name;
	_applyReportTypeState(f, true, true); 
}

function onchange$Period(o) {
	var f = o.parentForm;
	var bcTheo = f.getItemValue('bc_theo');
	var thang = f.getItemValue('thang');
	var quy = f.getItemValue('quy');
	var nam = f.getItemValue('nam');

	if (!nam) return;

	var ngay1, ngay2;
	switch(bcTheo){
		case 1: 
			if (thang && thang >= 1 && thang <= 12) {
				ngay1 = new Date(nam, thang - 1, 1);
				ngay2 = new Date(nam, thang, 0);
				f.setItemValue('ngay1', ngay1);
				f.setItemValue('ngay2', ngay2);
			}
			break;
		case 2: 
			if (quy && quy >= 1 && quy <= 4) {
				var startMonth = (quy - 1) * 3;
				ngay1 = new Date(nam, startMonth, 1);
				ngay2 = new Date(nam, startMonth + 3, 0);
				f.setItemValue('ngay1', ngay1);
				f.setItemValue('ngay2', ngay2);
			}
			break;
		case 3: 
			ngay1 = new Date(nam, 0, 1);
			ngay2 = new Date(nam, 11, 31);
			f.setItemValue('ngay1', ngay1);
			f.setItemValue('ngay2', ngay2);
			break;
		}
}
function _applyReportTypeState(f, focus, resetField) {
	var bcTheo = f.getItemValue('bc_theo');
	var ngay1Item = f.getItem('ngay1');
	var ngay2Item = f.getItem('ngay2');
	var thangItem = f.getItem('thang');
	var quyItem = f.getItem('quy');
	var namItem = f.getItem('nam');

	if(resetField){
		_resetPeriodFields(f);
	}
	var nextFocusItem = null;
	switch(bcTheo){
		case 0: 
			ngay1Item.disabled = false;
			ngay2Item.disabled = false;
			thangItem.disabled = true;
			quyItem.disabled = true; 
			namItem.disabled = true;
			$common.setVisible(ngay1Item.a, true);
			$common.setVisible(ngay2Item.a, true);
			$common.setVisible(thangItem.a, false);
			$common.setVisible(namItem.a, false);
			$common.setVisible(quyItem.a, false);
			nextFocusItem = ngay1Item;
			break;
		case 1:			
			ngay1Item.disabled = true;
			ngay2Item.disabled = true;
			thangItem.disabled = false;
			quyItem.disabled = true;
			namItem.disabled = false;
			$common.setVisible(ngay1Item.a, false);
			$common.setVisible(ngay2Item.a, false);
			$common.setVisible(thangItem.a, true);
			$common.setVisible(quyItem.a, false);
			$common.setVisible(namItem.a, true);
			nextFocusItem = thangItem;			
			break;
		case 2:
			ngay1Item.disabled = true;
			ngay2Item.disabled = true;
			thangItem.disabled = true;
			quyItem.disabled = false;
			namItem.disabled = false;
			$common.setVisible(ngay1Item.a, false);
			$common.setVisible(ngay2Item.a, false);
			$common.setVisible(thangItem.a, false);
			$common.setVisible(namItem.a, true);
			$common.setVisible(quyItem.a, true);
			nextFocusItem = quyItem;	
			break;
		case 3:
			ngay1Item.disabled = true;
			ngay2Item.disabled = true;
			thangItem.disabled = true;
			quyItem.disabled = true;
			namItem.disabled = false;
			$common.setVisible(ngay1Item.a, false);
			$common.setVisible(ngay2Item.a, false);
			$common.setVisible(thangItem.a, false);
			$common.setVisible(namItem.a, true);
			$common.setVisible(quyItem.a, false);
			nextFocusItem = namItem;	
			break;
		default:
			break;
	}
	if (nextFocusItem) {
		setTimeout(function() {
			nextFocusItem.focus();
		}, 50);
	}
}
function _resetPeriodFields(f) {
	var fieldsToReset = ['thang', 'quy', 'nam'];

	fieldsToReset.forEach(function(fieldName) {
		var item = f.getItem(fieldName);
			if (item) {
				f.setItemValue(fieldName, null);
			}
	});
}
function _setVisible(f, names, visible) {
	for (var i = 0; i < names.length; i++) {
		var it = f.getItem(names[i]);
		if (it && it.a) $common.setVisible(it.a, !!visible);
	}
}
